import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../providers/cart_provider.dart';
import 'order_confirmation_screen.dart';
class CheckoutScreen extends StatefulWidget { const CheckoutScreen({super.key}); @override State<CheckoutScreen> createState()=>_CheckoutScreenState(); }
class _CheckoutScreenState extends State<CheckoutScreen>{String method='cod';bool busy=false;Future<void> place()async{final p=context.read<CartProvider>();setState(()=>busy=true);final ref=FirebaseFirestore.instance.collection('orders').doc();await ref.set({'orderId':ref.id,'userId':FirebaseAuth.instance.currentUser!.uid,'items':p.items.map((x)=>x.toMap()).toList(),'totalAmount':p.subtotal,'deliveryCharge':p.delivery,'discount':p.discount,'grandTotal':p.total,'paymentMethod':method,'status':'placed','createdAt':FieldValue.serverTimestamp(),'estimatedDelivery':Timestamp.fromDate(DateTime.now().add(const Duration(minutes:45)))});await FirebaseFirestore.instance.doc('cart/${FirebaseAuth.instance.currentUser!.uid}').delete().catchError((_){ });if(mounted)Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>OrderConfirmationScreen(orderId:ref.id,total:p.total)),(r)=>r.isFirst);}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Checkout')),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('Payment method',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),RadioListTile(value:'cod',groupValue:method,onChanged:(v)=>setState(()=>method=v!),title:const Text('Cash on Delivery')),RadioListTile(value:'razorpay_test',groupValue:method,onChanged:(v)=>setState(()=>method=v!),title:const Text('Online payment (Razorpay test mode)')),const SizedBox(height:20),FilledButton(onPressed:busy?null:place,child:Text(busy?'Placing order…':'Place order'))]));}
